"""Durable recovery helpers for the replicated KV store."""

import os
import tempfile


def atomic_write(path, data):
    """Atomically replace *path* and fsync the file and its directory."""
    directory = os.path.dirname(path) or '.'
    fd, temporary = tempfile.mkstemp(prefix='.' + os.path.basename(path) + '.',
                                     dir=directory)
    try:
        view = memoryview(data.encode() if isinstance(data, str) else data)
        with os.fdopen(fd, 'wb') as stream:
            while view:
                written = os.write(stream.fileno(), view)
                view = view[written:]
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        temporary = None
    finally:
        if temporary is not None:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass

    dir_fd = os.open(directory, os.O_RDONLY | getattr(os, 'O_DIRECTORY', 0))
    try:
        os.fsync(dir_fd)
    finally:
        os.close(dir_fd)


def load_index(path):
    """Load a durable integer index, returning -1 when it does not exist."""
    if not os.path.exists(path):
        return -1
    with open(path, 'rb') as stream:
        value = int(stream.read().strip())
    if value < -1:
        raise ValueError(f"invalid index in {path}: {value}")
    return value


def load_manifest(path):
    """Compatibility wrapper for the persisted sync point."""
    return load_index(path)


def save_manifest(path, idx):
    """Persist the sync point."""
    atomic_write(path, str(idx))


def get_replay_target(ack_index, manifest_path):
    """Use the highest index known to be durably acknowledged.

    The two metadata files are updated in separate operations.  Taking their
    maximum is safe: both only ever contain committed indexes, and this also
    handles a crash between updating the two files.
    """
    return max(ack_index, load_manifest(manifest_path))


def on_promote(state, ack_index):
    """Apply every entry acknowledged before this node became leader."""
    if ack_index >= 0:
        state.apply_through(ack_index)
    return ack_index
