#!/usr/bin/env python3
"""Replicated key-value store with a durable write-ahead log."""

import asyncio
import json
import os
import sys

import recovery

DATA_DIR = "/app/data"


class WAL:
    """A fsynced, line-oriented write-ahead log."""

    def __init__(self, path):
        self.path = path
        self.entries = []
        self._offsets = []
        os.makedirs(os.path.dirname(path), exist_ok=True)
        self._load()

    @staticmethod
    def _valid_entry(value):
        return (
            isinstance(value, dict)
            and value.get('op') in ('SET', 'DEL')
            and isinstance(value.get('key'), str)
            and (value['op'] != 'SET' or 'value' in value)
        )

    def _load(self):
        if not os.path.exists(self.path):
            return
        with open(self.path, 'rb') as stream:
            raw = stream.read()

        entries = []
        offsets = []
        position = 0
        while position < len(raw):
            newline = raw.find(b'\n', position)
            end = len(raw) if newline < 0 else newline + 1
            try:
                entry = json.loads(raw[position:end].strip().decode('utf-8'))
                if not self._valid_entry(entry):
                    raise ValueError("invalid WAL entry")
                entries.append(entry)
                offsets.append(end)
            except (UnicodeDecodeError, json.JSONDecodeError, ValueError):
                # A partial final record can result from a process crash during
                # append.  It was never acknowledged, so discard only that tail.
                if newline >= 0 and position != 0:
                    raise
                if newline >= 0:
                    raise
                break
            position = end

        if len(entries) != len(offsets) or len(raw) not in (0, offsets[-1] if offsets else 0):
            with open(self.path, 'r+b') as stream:
                stream.truncate(offsets[-1] if offsets else 0)
                stream.flush()
                os.fsync(stream.fileno())

        self.entries = entries
        self._offsets = offsets

    def append(self, entry):
        if not self._valid_entry(entry):
            raise ValueError(f"invalid WAL entry: {entry!r}")
        payload = json.dumps(entry, separators=(',', ':')) + '\n'
        encoded = payload.encode('utf-8')
        fd = os.open(self.path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        try:
            old_size = os.fstat(fd).st_size
            view = memoryview(encoded)
            while view:
                written = os.write(fd, view)
                if written <= 0:
                    raise OSError("short WAL write")
                view = view[written:]
            os.fsync(fd)
        finally:
            os.close(fd)

        self.entries.append(entry)
        self._offsets.append(old_size + len(encoded))
        return len(self.entries) - 1

    def truncate(self, index):
        """Durably discard all entries after *index*.

        Index is the usual inclusive WAL index, and -1 denotes an empty log.
        Unacknowledged entries are never allowed to become committed because
        of a subsequent operation or FLUSH.
        """
        if index >= self.last_index:
            return
        if index < -1:
            raise ValueError("WAL index below -1")
        length = self._offsets[index] if index >= 0 else 0
        fd = os.open(self.path, os.O_WRONLY | os.O_CREAT, 0o600)
        try:
            os.ftruncate(fd, length)
            os.fsync(fd)
        finally:
            os.close(fd)
        self.entries = self.entries[:index + 1]
        self._offsets = self._offsets[:index + 1]

    @property
    def last_index(self):
        return len(self.entries) - 1 if self.entries else -1


