            await writer.wait_closed()
            return response.decode().strip() == f"ACK {idx}"
        except Exception:
            return False

    async def _send_commit(self, idx):
        try:
            reader, writer = await asyncio.open_connection(self.peer_host,
                                                           self.peer_port)
            writer.write(f"COMMIT {idx}\n".encode())
            await writer.drain()
            response = await asyncio.wait_for(reader.readline(), timeout=5.0)
            writer.close()
            await writer.wait_closed()
            return response.decode().strip() == f"ACK {idx}"
        except Exception:
            return False

    async def run(self):
        server = await asyncio.start_server(self._handle, '0.0.0.0', self.port)
        async with server:
            await server.serve_forever()


